#include <bits/stdc++.h>
using namespace std;

long long gcd(long long a, long long b) {
    while (b) {
        a %= b;
        swap(a, b);
    }
    return a;
}

int main() {
    cout << gcd(48, 18) << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

long long gcd(long long a, long long b) {
    while (b) {
        a %= b;
        swap(a, b);
    }
    return a;
}

int main() {
    vector<long long> a = {12, 18, 30};
    long long g = 0;

    for (long long x : a) {
        g = gcd(g, x);
    }

    cout << g << '\n';
    return 0;
}
